import { mkdir, readFile, rename, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { verifyEngineArtifact } from '../../scripts/assert-engine.mjs';

const mobile = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const root = path.resolve(mobile, '..');
const events = ['222', '333', '444', '555', '666', '777', '333oh', '333bf', '444bf', '555bf', 'minx', 'pyram', 'skewb', 'sq1', 'fto', 'clock'];

export function makeEngineDocument({ source, runtime, manifest, license }) {
  // Keep the verified generated algorithm intact. Only replace its final module
  // export with a private bridge in the same lexical scope. Unexpected compiler
  // output fails instead of silently shipping a different transform.
  const exports = /export\s*\{([^}]+)\};?\s*$/;
  const match = source.match(exports);
  if (!match || source.slice(0, match.index).match(/\b(?:import|export)\s*[({*]/)) throw new Error('Unexpected TNoodle module format.');
  const names = Object.fromEntries(match[1].split(',').map(entry => {
    const pair = entry.trim().match(/^([\w$]+)\s+as\s+(\w+)$/);
    if (!pair) throw new Error('Unexpected TNoodle export.');
    return [pair[2], pair[1]];
  }));
  if (!names.generate || !names.engineVersion) throw new Error('TNoodle production exports are missing.');
  const configuration = { channel: '__CCS_ENGINE_CHANNEL__', engineVersion: manifest.engineVersion, events,
    sha256: manifest.sha256, source: manifest.source, license };
  const script = `(function(){\n${source.slice(0, match.index)}\n${runtime}\ninstallEngineBridge({engineVersion:${names.engineVersion},generate:${names.generate},draw:${names.draw ?? 'undefined'}},${JSON.stringify(configuration)});\n})();`;
  if (/<\/script/i.test(script)) throw new Error('Inline script contains a closing script tag.');
  return '<!doctype html><html><head><meta charset="utf-8">'
    + '<meta http-equiv="Content-Security-Policy" content="default-src \'none\'; script-src \'unsafe-inline\'; connect-src \'none\'; img-src \'none\'; style-src \'none\'; object-src \'none\'; base-uri \'none\'; form-action \'none\'">'
    + '<title>Local scramble engine</title></head><body><script>' + script + '</script></body></html>';
}

export async function bundleEngine(engineDirectory = path.join(root, 'public/engine')) {
  const [bytes, manifestText, proofText, lockText, license, runtime] = await Promise.all([
    readFile(path.join(engineDirectory, 'tnoodle.js')),
    readFile(path.join(engineDirectory, 'manifest.json'), 'utf8'),
    readFile(path.join(engineDirectory, 'conformance.json'), 'utf8'),
    readFile(path.join(root, 'engine/upstream-lock.json'), 'utf8'),
    readFile(path.join(engineDirectory, 'LICENSE.txt'), 'utf8'),
    readFile(path.join(mobile, 'src/engine/webview-runtime.js'), 'utf8'),
  ]);
  const manifest = JSON.parse(manifestText);
  verifyEngineArtifact({ bytes, manifest, proof: JSON.parse(proofText), lock: JSON.parse(lockText) });
  if (!license.includes('GNU GENERAL PUBLIC LICENSE')) throw new Error('The engine license is missing.');
  const html = makeEngineDocument({ source: bytes.toString('utf8'), runtime, manifest, license });
  const output = path.join(mobile, 'assets/engine.generated.ts');
  const module = '// Generated by mobile/scripts/engine-bundle.mjs. Do not edit or commit.\n'
    + `export const ENGINE_VERSION = ${JSON.stringify(manifest.engineVersion)};\n`
    + `export const ENGINE_SHA256 = ${JSON.stringify(manifest.sha256)};\n`
    + `export const ENGINE_DOCUMENT = ${JSON.stringify(html)};\n`;
  await mkdir(path.dirname(output), { recursive: true });
  await writeFile(output + '.tmp', module);
  await rename(output + '.tmp', output);
  return { output, bytes: Buffer.byteLength(module), engineSha256: manifest.sha256 };
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const args = process.argv.slice(2);
  if (args.length && (args.length !== 2 || args[0] !== '--engine-dir')) throw new Error('Usage: node scripts/engine-bundle.mjs [--engine-dir /path/to/verified/engine]');
  try {
    const result = await bundleEngine(args.length ? path.resolve(args[1]) : undefined);
    console.log(`Bundled verified local engine (${result.bytes} bytes, SHA-256 ${result.engineSha256}).`);
  } catch (error) {
    console.error('Mobile engine preparation failed. Build and verify TNoodle first, or provide a matching verified engine directory.');
    console.error(error.message); process.exitCode = 1;
  }
}
